insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_these_those_homework_q01_finish","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\the_these_those_homework.yaml","source_metadata":{}},{"key":"the_these_those_homework_q01_start","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\the_these_those_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_these_those_homework_q01_finish","locale":"he","line_order":0,"content":"בזכותכם אני מוכן. מחר אראה לראש הכפר את כל החווה, מהחזירים שלידנו ועד העצים שמעבר לנהר.","line_format":"plain_text"},{"dialogue_key":"the_these_those_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: The = ה' הידיעה. These = האלה, על כמה דברים קרובים. Those = ההם, על כמה דברים רחוקים.","line_format":"plain_text"},{"dialogue_key":"the_these_those_homework_q01_finish","locale":"he","line_order":2,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"the_these_those_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב, חברים. ראש הכפר עדיין מספר לכולם על התירס שהבאתם לו.","line_format":"plain_text"},{"dialogue_key":"the_these_those_homework_q01_start","locale":"he","line_order":1,"content":"מחר הוא בא לראות את החווה, ואני רוצה להראות לו באנגלית מה קרוב אלינו ומה רחוק.","line_format":"plain_text"},{"dialogue_key":"the_these_those_homework_q01_start","locale":"he","line_order":2,"content":"היום אין כלל חדש. תראו לי לבד שאתם זוכרים את The, These ו־Those. הכול מחכה לכם ליד המדורה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
